engine.readUserStats:
function readUserStats() {
  try {
    var raw = window.eli && window.eli.compat
      ? window.eli.compat.lsGet("eli_user_stats")
      : (typeof localStorage !== "undefined" ? localStorage.getItem("eli_user_stats") : null);
    return raw ? JSON.parse(raw) : null;
  } catch (e) { return null; }
}

// Project the stat blob into the canonical sidebar row list.
// Filters out zero-value rows so the sidebar stays tight on fresh installs.
// FROM v2 _renderSidebarStats shape (mirrors v3 kernel hardcoded rows).

engine.buildStatRows:
function buildStatRows(stats) {
  if (!stats || typeof stats !== "object") return [];
  var defs = [
    { icon: "📅", value: stats.totalActiveDays, label: "Days",          key: "totalActiveDays" },
    { icon: "📄", value: stats.docsReviewed,    label: "Docs reviewed", key: "docsReviewed" },
    { icon: "📝", value: stats.draftsCreated,   label: "Drafts built",  key: "draftsCreated" },
    { icon: "🛡️", value: stats.errorsFixed,    label: "Errors fixed",  key: "errorsFixed" },
    { icon: "⚖️", value: stats.risksFound,     label: "Risks found",   key: "risksFound" },
  ];
  return defs.filter(function (r) { return r.value; });
}

// Engine entry — convenience wrapper for caller orchestration.

engine.analyze:
function analyze(input, providers) {
  var stats = readUserStats();
  var rows = buildStatRows(stats);
  return Promise.resolve({
    rows: rows,
    raw: stats,
    overview: rows.length + " active stat" + (rows.length === 1 ? "" : "s"),
    provenance: {
      kernelVersion: (window.eli && window.eli.kernelVersion) || "v3",
      toolVersion: "v3.0",
      docHash: null,
      timestamp: Date.now(),
    },
  });
}

view.renderSidebarStats:
function renderSidebarStats(opts) {
  var mount = opts.mount;
  if (!mount) return;
  var rows = opts.rows || [];
  var onOpenTrophies = opts.onOpenTrophies || function () {};
  if (!rows.length) {
    // No stats yet — render nothing rather than a zeroed-out skeleton.
    return null;
  }
  var box = document.createElement("div");
  box.className = "_eli3_sidebar_stats";
  rows.forEach(function (r) {
    var row = document.createElement("div");
    row.className = "_eli3_sidebar_stat_row";
    row.title = r.label;
    var ic = document.createElement("span");
    ic.className = "_eli3_sidebar_stat_icon";
    ic.textContent = r.icon;
    var num = document.createElement("span");
    num.className = "_eli3_sidebar_stat_num";
    num.textContent = r.value;
    var lbl = document.createElement("span");
    lbl.className = "_eli3_sidebar_stat_label";
    lbl.textContent = r.label;
    row.appendChild(ic);
    row.appendChild(num);
    row.appendChild(lbl);
    box.appendChild(row);
  });
  mount.appendChild(box);
  return box;
}

// Redline detector — small chip that pulses when the doc has tracked
// changes. Click → dispatches to review_redlines tool (or shows a hint
// when the tool isn't installed yet). Hidden when count === 0.
//
// `opts.count` is the live tracked-changes count; init.js subscribes to
// doc:dirty + polls eli.host.runRaw → body.getTrackedChanges to keep
// it fresh.

view.renderRedlineBox:
function renderRedlineBox(opts) {
  var mount = opts.mount;
  if (!mount) return null;
  var count = Number(opts.count || 0);
  var onClick = opts.onClick || function () {};
  if (!count) return null;
  var box = document.createElement("div");
  box.className = "_eli3_sidebar_redline";
  box.title = count + " tracked change" + (count === 1 ? "" : "s") + " in this document";
  box.innerHTML =
    '<span class="_eli3_sidebar_redline_icon">📝</span>' +
    '<span class="_eli3_sidebar_redline_count">' + count + '</span>' +
    '<span class="_eli3_sidebar_redline_label">redline' + (count === 1 ? "" : "s") + '</span>';
  box.onclick = onClick;
  mount.appendChild(box);
  return box;
}

jsonTools.init:
function init(eli) {
  var bundle = eli.tools._loaded["eli_stats"];
  if (!bundle) return;
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var readUserStats     = efns.readUserStats;
  var buildStatRows     = efns.buildStatRows;
  var renderSidebarStats = vfns.renderSidebarStats;
  var renderRedlineBox   = vfns.renderRedlineBox;
  if (!readUserStats || !renderSidebarStats) {
    eli.log.event("tool", "eli_stats_load_failed", {
      hasRead: !!readUserStats, hasView: !!renderSidebarStats,
    });
    return;
  }

  // Cached tracked-changes count. Updated on doc:dirty + on a 30s
  // backstop timer. NOT polled every selection-change — that would
  // burn Word.run budget for data the user rarely consults.
  var _redlineCount = 0;
  var _redlineLoaded = false;

  // Scan the doc for tracked changes. Cheap relative to body.text —
  // getTrackedChanges returns a collection we just load the count of.
  function _scanRedlines() {
    if (!eli.host || !eli.host.runRaw) return Promise.resolve(0);
    return eli.host.runRaw("eli_stats:redline_scan", function (context) {
      var changes = context.document.body.getTrackedChanges();
      changes.load("items");
      return context.sync().then(function () {
        return (changes.items || []).length;
      });
    }).catch(function () { return 0; });
  }

  function _refreshRedlines() {
    return _scanRedlines().then(function (n) {
      var changed = n !== _redlineCount || !_redlineLoaded;
      _redlineCount = n;
      _redlineLoaded = true;
      if (changed) {
        try {
          if (eli.dashboard && typeof eli.dashboard.refresh === "function") {
            eli.dashboard.refresh();
          }
        } catch (e) { /* tolerate */ }
      }
      return n;
    });
  }

  // ─── Sidebar slot builder ───────────────────────────────────────
  // Called by kernel's _paintSidebarSlots whenever the sidebar renders.
  // Builder receives { mount, ident, refresh } — paints stat rows into
  // mount then appends the redline chip below.
  function _build(opts) {
    var stats = readUserStats();
    var rows = buildStatRows(stats);
    renderSidebarStats({
      mount: opts.mount,
      rows: rows,
    });
    if (renderRedlineBox && _redlineCount > 0) {
      renderRedlineBox({
        mount: opts.mount,
        count: _redlineCount,
        onClick: function () {
          // Dispatch to review_redlines tool if installed; otherwise
          // toast a hint. The handoff matches the v2 banner-click flow.
          var handler = eli.get && eli.get("tile", "app_review_redlines");
          if (typeof handler === "function") {
            try { handler(); return; } catch (e) {}
          }
          if (typeof showToast === "function") {
            showToast(_redlineCount + " tracked change" +
              (_redlineCount === 1 ? "" : "s") +
              " — install Review Redlines to manage them.", "info");
          }
        },
      });
    }
  }

  // Register the sidebar slot. v2 had this inline in the kernel; v3
  // offloads it so the kernel doesn't know about stats at all.
  if (eli.dashboard && typeof eli.dashboard.registerSidebarSlot === "function") {
    eli.dashboard.registerSidebarSlot("eli_stats", _build);
  }

  // Kick a one-shot redline scan on init so the chip can paint on the
  // first sidebar render. Subscribe to doc:dirty for live updates.
  // Backstop timer at 30s catches event misses (window blur, etc.).
  _refreshRedlines();
  if (eli.bus && typeof eli.bus.on === "function") {
    eli.bus.on("doc:dirty", function () {
      // Debounce — doc:dirty can fire many times during typing.
      if (init._redlineDebounce) return;
      init._redlineDebounce = setTimeout(function () {
        init._redlineDebounce = null;
        _refreshRedlines();
      }, 800);
    });
  }
  // Backstop poll — every 30s rescan in case bus events dropped.
  setInterval(function () { _refreshRedlines(); }, 30 * 1000);

  eli.log.event("tool", "eli_stats_initialized", {});
}

jsonTools.css:
/* eli_stats tool styles — sidebar stat list + redline-detector chip.
   Injected as <style data-tool="eli_stats">. */

/* Stat rows — vertical list, kernel-defined classes preserved for
   backward compat with the v3 kernel's hardcoded styles (which the
   tool replaces). */
._eli3_sidebar_stats {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 8px 0;
}
._eli3_sidebar_stat_row {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 3px 4px;
  font: 500 11px/1 'Inter', sans-serif;
  color: #cbd5e1;
  cursor: default;
}
._eli3_sidebar_stat_icon { font-size: 13px; }
._eli3_sidebar_stat_num {
  font-weight: 800;
  color: #f8fafc;
  min-width: 24px;
  text-align: right;
}
._eli3_sidebar_stat_label {
  font-size: 10px;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.3px;
}
body.light-mode ._eli3_sidebar_stat_row { color: #475569; }
body.light-mode ._eli3_sidebar_stat_num { color: #0f172a; }
body.light-mode ._eli3_sidebar_stat_label { color: #64748b; }

/* Redline detector chip — only renders when the doc has tracked changes.
   Pulses red so it's visually loud; click hands off to Review Redlines. */
._eli3_sidebar_redline {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  margin-top: 8px;
  background: linear-gradient(135deg, #b91c1c 0%, #7c1d12 100%);
  color: #fff7f0;
  border: 1px solid rgba(255, 247, 240, 0.25);
  cursor: pointer;
  font: 700 10px/1 'Inter', sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  transition: transform 0.12s, box-shadow 0.15s;
  box-shadow: 0 0 0 0 rgba(185, 28, 28, 0.55);
  animation: _eli3_sidebar_redline_pulse 2.6s ease-in-out infinite;
}
._eli3_sidebar_redline:hover {
  transform: translateY(-1px);
  box-shadow: 0 2px 8px rgba(185, 28, 28, 0.45);
}
._eli3_sidebar_redline_icon { font-size: 12px; }
._eli3_sidebar_redline_count {
  font-weight: 900;
  font-size: 14px;
  color: #fff;
}
._eli3_sidebar_redline_label { opacity: 0.92; }
@keyframes _eli3_sidebar_redline_pulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(185, 28, 28, 0.50); }
  50%      { box-shadow: 0 0 0 6px rgba(185, 28, 28, 0.00); }
}
